from gurobipy import Model, GRB, quicksum

def build_and_solve():
    shipping_costs_source = '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP11/shipping_costs.csv'
    facility_costs_source = '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP11/facility_costs.csv'
    demand_requirements_source = '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP11/demand_requirements.csv'
    factories = []
    dcs = []
    for rec in LEGACY_RECORDS:
        if rec['source'] == shipping_costs_source:
            i = rec['values']['Origin']
            if i not in factories:
                factories.append(i)
            for j in rec['values']:
                if j != 'Origin' and j not in dcs:
                    dcs.append(j)
    factories = sorted(factories, key=lambda x: int(x[1:]))
    dcs = sorted(dcs, key=lambda x: int(x[1:]))
    c = {}
    for rec in LEGACY_RECORDS:
        if rec['source'] == shipping_costs_source:
            i = rec['values']['Origin']
            for j in dcs:
                c[i, j] = float(rec['values'][j])
    f_list = [0, 175, 300, 375, 500, 200, 260, 220, 320, 280, 350, 420, 470, 520, 560]
    cap_list = [30, 10, 20, 30, 40, 20, 25, 30, 35, 20, 40, 25, 30, 50, 45]
    if len(factories) != len(f_list) or len(factories) != len(cap_list):
        raise ValueError('Mismatch in number of factories and cost/capacity lists')
    f = {factories[i]: float(f_list[i]) for i in range(len(factories))}
    cap = {factories[i]: float(cap_list[i]) for i in range(len(factories))}
    d_list = [30, 25, 20, 35, 25, 30, 25, 30]
    if len(dcs) != len(d_list):
        raise ValueError('Mismatch in number of DCs and demand list')
    d = {dcs[j]: float(d_list[j]) for j in range(len(dcs))}
    for i in factories:
        for j in dcs:
            if (i, j) not in c:
                raise ValueError(f'Missing shipping cost for ({i},{j})')
    for i in factories:
        if i not in f or i not in cap:
            raise ValueError(f'Missing facility cost or capacity for {i}')
    for j in dcs:
        if j not in d:
            raise ValueError(f'Missing demand for {j}')
    m = Model()
    m.Params.MIPGap = 0.0001
    y_vars = m.addVars(factories, vtype=GRB.BINARY, lb=0, ub=1, name='')
    x_vars = m.addVars(factories, dcs, vtype=GRB.CONTINUOUS, lb=0, name='')
    m.setObjective(quicksum((f[i] * y_vars[i] for i in factories)) + quicksum((c[i, j] * x_vars[i, j] for i in factories for j in dcs)), GRB.MINIMIZE)
    for j in dcs:
        m.addConstr(quicksum((x_vars[i, j] for i in factories)) == d[j], name='dem_' + j)
    for i in factories:
        m.addConstr(quicksum((x_vars[i, j] for j in dcs)) <= cap[i] * y_vars[i], name='cap_' + i)
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(m.ObjVal)
        for v in m.getVars():
            print(v.VarName, v.X)
    else:
        print(m.Status)
    return m
m = build_and_solve()